#[verus::spec]
fn solve(x: i8) -> u8 {
    // Requires that the input x is within the valid range for i8
    // Ensures that the output is a valid rotation in the range [0, 3]
    // The function normalizes the input angle to the range [0, 360)
    // and finds the best rotation to minimize deviation from vertical.

    // Precondition: x is a valid i8
    // Postcondition: return value is in the range [0, 3]
    // Invariant: 0 <= min_deviation <= 180
    // Invariant: 0 <= best_rotation <= 3
    // Decreases clause: The loop variable r decreases from 4 to 0

    let normalized_angle = ((x % 360 + 360) % 360) as u32;

    let mut min_deviation: u32 = 180; // Maximum possible deviation
    let mut best_rotation: u8 = 0;

    // Loop invariant: 0 <= r <= 4
    // Loop invariant: min_deviation is the minimum deviation found so far
    // Loop invariant: best_rotation is the rotation corresponding to min_deviation
    for r in 0..4 {
        // Calculate the resulting angle after r quarter-turns
        let resulting_angle = (normalized_angle + 90 * r) % 360;

        // Calculate the deviation from vertical
        let deviation = resulting_angle.min(360 - resulting_angle);

        // Update the best rotation if we found a smaller deviation
        if deviation < min_deviation {
            min_deviation = deviation;
            best_rotation = r;
        }
    }

    // Ensure that the best_rotation is in the range [0, 3]
    assert!(best_rotation <= 3);
    best_rotation
}